import dns from 'node:dns';
import net from 'node:net';

/**
 * Refuses every non-loopback network attempt in the current test process and records it, so a
 * metadata-lookup test that would reach a real service fails instead. It patches `fetch`, socket
 * connections (which also covers `https.request`), `dns.lookup` and every resolver method, in both
 * callback and promise forms. Loopback `fetch`, loopback sockets and IPC paths keep working; resolver
 * queries are refused for every name. Install it per file and
 * call `restore()` in an `after` hook, asserting that `attempts` stayed empty.
 */
export class NetworkGuardError extends Error {
    constructor(readonly target: string) { super(`Network access refused in tests: ${target}`); this.name = 'NetworkGuardError'; }
}

const resolverMethods = ['resolve', 'resolve4', 'resolve6', 'resolveAny', 'resolveCaa', 'resolveCname', 'resolveMx', 'resolveNaptr',
    'resolveNs', 'resolvePtr', 'resolveSoa', 'resolveSrv', 'resolveTlsa', 'resolveTxt', 'reverse'] as const;

/** `localhost`, 127.0.0.0/8, `::1` and IPv4-mapped loopback are local; every other host is refused. */
const isLoopback = (host: string) => {
    const name = host.replace(/^\[|\]$/g, '').toLowerCase();
    return name === 'localhost' || name.endsWith('.localhost') || name === '::1' || /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(name)
        || /^::ffff:127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(name);
};

type Patch = { target: Record<string, unknown>; key: string; original: unknown };

export const installNetworkGuard = (): { attempts: readonly string[]; restore(): void } => {
    const attempts: string[] = [];
    const patches: Patch[] = [];
    const patch = (target: object, key: string, replacement: unknown) => {
        const record = target as Record<string, unknown>;
        if (typeof record[key] !== 'function') return;
        patches.push({ target: record, key, original: record[key] });
        record[key] = replacement;
    };
    const refuse = (kind: string, target: string) => { attempts.push(`${kind}:${target}`); return new NetworkGuardError(target); };

    const originalFetch = globalThis.fetch;
    patch(globalThis, 'fetch', async (input: unknown, init?: RequestInit) => {
        const href = typeof input === 'string' ? input : input instanceof URL ? input.href : String((input as { url?: unknown })?.url ?? input);
        let host: string | null = null;
        try { host = new URL(href).hostname; } catch { /* an unparsable target is refused */ }
        if (host !== null && isLoopback(host)) return originalFetch(input as Parameters<typeof fetch>[0], init);
        throw refuse('fetch', host ?? href);
    });

    const connect = net.Socket.prototype.connect as (...args: unknown[]) => net.Socket;
    patch(net.Socket.prototype, 'connect', function (this: net.Socket, ...args: unknown[]) {
        // Node passes already-normalized arguments as one array internally.
        const first = Array.isArray(args[0]) ? args[0][0] : args[0];
        let host = 'localhost', path: unknown;
        if (first && typeof first === 'object') { host = String((first as { host?: unknown }).host ?? 'localhost'); path = (first as { path?: unknown }).path; }
        else if (typeof first === 'string' && !/^\d+$/.test(first)) path = first;
        else if (typeof args[1] === 'string') host = args[1];
        // HTTP agents pass `path: null`; only a non-empty path is an IPC connection.
        if ((typeof path === 'string' && path) || isLoopback(host)) return connect.apply(this, args);
        const error = refuse('connect', host);
        process.nextTick(() => this.destroy(error));
        return this;
    });

    const lookup = dns.lookup as (...args: unknown[]) => unknown;
    patch(dns, 'lookup', (...args: unknown[]) => {
        const hostname = String(args[0]);
        if (isLoopback(hostname)) return lookup(...args);
        const callback = args[args.length - 1];
        const error = refuse('lookup', hostname);
        if (typeof callback === 'function') process.nextTick(() => callback(error));
        return undefined;
    });
    const promiseLookup = dns.promises.lookup as (...args: unknown[]) => Promise<unknown>;
    patch(dns.promises, 'lookup', async (...args: unknown[]) => {
        const hostname = String(args[0]);
        if (isLoopback(hostname)) return promiseLookup(...args);
        throw refuse('lookup', hostname);
    });
    patch(dns, 'lookupService', (...args: unknown[]) => {
        const callback = args[args.length - 1];
        const error = refuse('lookupService', String(args[0]));
        if (typeof callback === 'function') process.nextTick(() => callback(error));
    });
    patch(dns.promises, 'lookupService', async (...args: unknown[]) => { throw refuse('lookupService', String(args[0])); });

    for (const method of resolverMethods) {
        const callbackForm = (...args: unknown[]) => {
            const callback = args[args.length - 1];
            const error = refuse(method, String(args[0]));
            if (typeof callback === 'function') process.nextTick(() => callback(error));
            return undefined;
        };
        const promiseForm = async (...args: unknown[]) => { throw refuse(method, String(args[0])); };
        patch(dns.Resolver.prototype, method, callbackForm);
        patch(dns, method, callbackForm);
        patch(dns.promises.Resolver.prototype, method, promiseForm);
        patch(dns.promises, method, promiseForm);
    }

    return {
        attempts,
        restore() {
            for (const { target, key, original } of patches.splice(0).reverse()) target[key] = original;
        }
    };
};
